                dirs.append((f"a{m.group(1)}", alpha_val, path, [int(m.group(2))]))
    else:
        pattern = os.path.join(SWEEP_DIR, "a*_s42")
        for path in sorted(glob.glob(pattern)):
            name = os.path.basename(path)
            m = re.match(r"a(\d{3})_s42", name)
            if m:
